#include <iostream>
#include <vector>
using namespace std;

int main() {
    long long n;
    int k;
    cin >> n >> k;

    vector<int> digits;
    while (n > 0) {
        digits.push_back(n % k);
        n /= k;
    }

    int sz = k + 1;
    vector<vector<long long>> mat(sz, vector<long long>(sz, 0));
    for (int j = 0; j <= k; ++j) {
        mat[0][j] = 1;
        mat[j][j] = 1;
    }

    auto matmul = [&](const vector<vector<long long>> &A, const vector<vector<long long>> &B) {
        vector<vector<long long>> C(sz, vector<long long>(sz, 0));
        for (int i = 0; i < sz; ++i)
            for (int j = 0; j < sz; ++j)
                for (int t = 0; t < sz; ++t)
                    C[i][j] = (C[i][j] + A[i][t] * B[t][j]) % 1000000007;
        return C;
    };

    auto matpow = [&](vector<vector<long long>> base, long long e) {
        vector<vector<long long>> res(sz, vector<long long>(sz, 0));
        for (int i = 0; i < sz; ++i) res[i][i] = 1;
        while (e > 0) {
            if (e & 1) res = matmul(res, base);
            base = matmul(base, base);
            e >>= 1;
        }
        return res;
    };

    auto jia = [&](const vector<vector<long long>> &x, int d) {
        vector<vector<long long>> ret(sz, vector<long long>(sz, 0));
        for (int i = 0; i <= k; ++i)
            for (int j = 0; j <= k; ++j) {
                int ni = (i + d) % k;
                int nj = (j + d) % k;
                if (i == k) ni = k;
                if (j == k) nj = k;
                ret[ni][nj] = x[i][j];
            }
        return ret;
    };

    vector<vector<long long>> A(sz, vector<long long>(sz, 0));
    for (int j = 0; j <= k; ++j) A[0][j] = 1;
    for (int j = 0; j <= k; ++j) A[j][j] = 1;

    vector<vector<long long>> baseA = A;
    vector<vector<long long>> ansA = A;

    vector<vector<long long>> ans(sz, vector<long long>(sz, 0));
    for (int i = 0; i < sz; ++i) ans[i][i] = 1;

    long long idx = 0;
    for (int i = (int)digits.size() - 1; i >= 0; --i) {
        for (int j = 0; j < digits[i]; ++j) {
            ans = matmul(ans, jia(baseA, (j + idx) % k));
        }
        idx = (idx + digits[i]) % k;
    }

    long long total = 0;
    for (int i = 0; i <= k; ++i) {
        total = (total + ans[i][k]) % 1000000007;
    }
    cout << total << endl;
    return 0;
}
